using System.Text.Json;
using FlotixPlatform.API.Analytics.Domain.Model.Commands;
using FlotixPlatform.API.Analytics.Domain.Model.ValueObjects;

namespace FlotixPlatform.API.Analytics.Domain.Model.Aggregates;

/// <summary>
///     Represents a fleet report generated by an owner with its filter parameters.
/// </summary>
/// <remarks>
///     This aggregate root keeps the metadata of a generated fuel or maintenance report and is immutable afterwards.
///     Audit timestamps (CreatedAt, UpdatedAt) are managed by the persistence layer.
/// </remarks>
public partial class Report
{
    /// <summary>
    ///     Protected parameterless constructor for EF Core.
    /// </summary>
    protected Report()
    {
        FilterParams = string.Empty;
    }

    /// <summary>
    ///     Creates a new Report from a generate report command.
    /// </summary>
    /// <remarks>
    ///     The period of the report is kept in <see cref="FilterParams"/> as JSON (e.g. {"from":"2026-08-01","to":"2026-08-31"}).
    /// </remarks>
    /// <param name="command">The GenerateReportCommand command</param>
    /// <exception cref="ArgumentNullException">Thrown when the command is null.</exception>
    /// <exception cref="ArgumentException">Thrown when the report type is not supported or the period is invalid.</exception>
    public Report(GenerateReportCommand command)
    {
        ArgumentNullException.ThrowIfNull(command);
        ArgumentOutOfRangeException.ThrowIfEqual(command.OwnerId, Guid.Empty);
        if (!Enum.IsDefined(command.ReportType))
            throw new ArgumentOutOfRangeException(nameof(command), "The report type is not supported.");
        if (command.From > command.To)
            throw new ArgumentException("The start of the period cannot be after its end.", nameof(command));

        OwnerId = command.OwnerId;
        ReportType = command.ReportType;
        FilterParams = JsonSerializer.Serialize(new { from = command.From, to = command.To });
        GeneratedDate = DateTimeOffset.UtcNow;
    }

    /// <summary>
    ///     Gets the server-generated identifier for this report.
    /// </summary>
    public Guid Id { get; private set; }

    /// <summary>
    ///     Gets the identifier of the owner user.
    /// </summary>
    public Guid OwnerId { get; private set; }

    /// <summary>
    ///     Gets the type of the report.
    /// </summary>
    public ReportType ReportType { get; private set; }

    /// <summary>
    ///     Gets the moment the report was generated.
    /// </summary>
    public DateTimeOffset GeneratedDate { get; private set; }

    /// <summary>
    ///     Gets the filters applied to the report (e.g. date range).
    /// </summary>
    public string FilterParams { get; private set; }
}
